import{WithParams}from"./WithParams.js";class Operator extends WithParams{onblamready(){this.c=this.context(),this.outNode=this.c.createGain(),this.mirrorParams({gain:this.outNode.gain})}connectGain(){this.envGainNode=this.c.createGain(),this.envGainNode.gain.value=0,this.envGainNode.connect(this.outNode)}connectInput(){this.node=this.c.createOscillator(),this.node.type=this.type,this.node.connect(this.envGainNode)}instantiate(note){this.connectGain(),this.connectInput(),this.node.frequency.value=this.setFreq(note),this.mirrorParams({detune:this.node.detune,freq:this.node.frequency,type:this.node})}stop(){this.prevEnvGainNode&&this.prevEnvGainNode.gain.linearRampToValueAtTime(0,this.time+this.release*this.beat)}envelope(){for(let pair of this.pairs)this.envGainNode.gain.linearRampToValueAtTime(pair[0],this.time+pair[1]*this.beat)}prePlay(note){this.stop(),this.instantiate(note),this.node&&this.node.start()}play(note,time){this.time=time||this.c.currentTime,this.prePlay(note),this.envelope(),this.fire("blam",{...this.instance,time:this.time},this),this.prevEnvGainNode=this.envGainNode}get type(){let value=this.getAttribute("type");return["square","sawtooth","triangle"].find(v=>v===value)||"sine"}set type(value){this.setAttribute("type",value)}get gain(){let value=this.getAttribute("gain");return value?parseFloat(value):1}set gain(value){this.setAttribute("gain",value)}get curve(){return this.getAttribute("curve")||"0 0, 1 0.005"}set curve(value){this.setAttribute("curve",value)}get out(){return this.getAttribute("out")}set out(value){this.setAttribute("out",value)}get release(){let value=this.getAttribute("release");return value?parseFloat(value):1}set release(value){this.setAttribute("release",value)}static get observedAttributes(){return["gain","curve","type"]}attributeChangedCallback(name,_,value){"curve"===name&&this.parseCurve(),super.attributeChangedCallback(name,_,value)}connectedCallback(){this.parseCurve()}}export{Operator};